package it.servizidigitali.gestionebandi.common.service;

/**
 * Servizio per la lettura dei flag di configurazione censiti tra i dati del bando
 * ({@code dato_bando} / {@code valore_dato_bando}).
 *
 * Espone metodi di business sui singoli flag, nascondendo ai chiamanti il recupero
 * del {@code DatoBando} per codice e del relativo {@code ValoreDatoBando} per bando.
 */
public interface DatoBandoFlagService {

    /**
     * Indica se per la domanda bando indicata la verifica della firma deve avvenire solo
     * rispetto alla data corrente (anziché rispetto al periodo di validità).
     *
     * Risolve la domanda bando nel relativo bando e delega a
     * {@link #isVerificaFirmaSoloDataOggiByBandoId(long)}.
     */
    boolean isVerificaFirmaSoloDataOggiByDomandaBandoId(long domandaBandoId);

    /**
     * Indica se per il bando indicato la verifica della firma deve avvenire solo rispetto
     * alla data corrente (anziché rispetto al periodo di validità), in base al flag
     * {@code ABILITA_FIRMA_DATA_ISTANZA} configurato sul bando.
     */
    boolean isVerificaFirmaSoloDataOggiByBandoId(long bandoId);
}

