package it.servizidigitali.gestionebandi.common.service.impl;

import com.liferay.portal.kernel.log.Log;
import com.liferay.portal.kernel.log.LogFactoryUtil;

import java.util.List;

import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Reference;

import it.servizidigitali.gestionebandi.common.enumeration.CodiceDatoBandoEnum;
import it.servizidigitali.gestionebandi.common.service.DatoBandoFlagService;
import it.servizidigitali.gestionebandi.model.DatoBando;
import it.servizidigitali.gestionebandi.model.DomandaBando;
import it.servizidigitali.gestionebandi.model.ValoreDatoBando;
import it.servizidigitali.gestionebandi.service.DatoBandoLocalService;
import it.servizidigitali.gestionebandi.service.DomandaBandoLocalService;
import it.servizidigitali.gestionebandi.service.ValoreDatoBandoLocalService;

@Component(name = "datoBandoFlagService", immediate = true, service = DatoBandoFlagService.class)
public class DatoBandoFlagServiceImpl implements DatoBandoFlagService {

    private static final Log log = LogFactoryUtil.getLog(DatoBandoFlagServiceImpl.class);

    @Reference
    private DomandaBandoLocalService domandaBandoLocalService;

    @Reference
    private DatoBandoLocalService datoBandoLocalService;

    @Reference
    private ValoreDatoBandoLocalService valoreDatoBandoLocalService;

    @Override
    public boolean isVerificaFirmaSoloDataOggiByDomandaBandoId(long domandaBandoId) {
        DomandaBando domandaBando = domandaBandoLocalService.fetchDomandaBando(domandaBandoId);
        if (domandaBando == null) {
            return false;
        }
        return isVerificaFirmaSoloDataOggiByBandoId(domandaBando.getBandoId());
    }

    @Override
    public boolean isVerificaFirmaSoloDataOggiByBandoId(long bandoId) {
        return isDatoBandoFlagAttivo(bandoId, CodiceDatoBandoEnum.ABILITA_FIRMA_DATA_ISTANZA);
    }

    /**
     * Verifica generica sul valore di un flag booleano censito tra i {@link CodiceDatoBandoEnum} per il bando indicato.
     * I flag DISABILITA_* funzionano come attivatori: valore "true" => funzionalità attiva.
     */
    private boolean isDatoBandoFlagAttivo(long bandoId, CodiceDatoBandoEnum codice) {
        try {
            DatoBando datoBando = datoBandoLocalService.findByCodice(codice.name());
            if (datoBando != null) {
                List<ValoreDatoBando> valori = valoreDatoBandoLocalService.findByBandoIdAndDatoBandoId(bandoId, datoBando.getDatoBandoId());
                if (valori != null && !valori.isEmpty()) {
                    return "true".equals(valori.get(0).getValore());
                }
            }
        } catch (Exception e) {
            log.error("Errore nel recupero del flag " + codice.name() + " per bandoId=" + bandoId + ": " + e.getMessage(), e);
        }
        return false;
    }
}

