    richiestaReferenteIstanzaLocalService.deleteRichiestaReferenteIstanza(richiestaReferenteIstanzaId);
}

private VerificaResponse verificaFirmaAllegato(AllegatoReferenteDTO allegato, boolean principale, long groupId, Contesto contesto, boolean verificaFirmaSoloDataOggi) throws ConfigurationException {
    GestioneReferenteGroupConfiguration configuration = configurationProvider.getGroupConfiguration(GestioneReferenteGroupConfiguration.class, groupId);
    List<String> tipiFileAmmessiList = new ArrayList<>();
    String formatiFirmaAmmessi = configuration.formatiFirmaAmmessi();
    if (Validator.isNotNull(formatiFirmaAmmessi)) {
        tipiFileAmmessiList = List.of(formatiFirmaAmmessi.split(","));
    }
    VerificaFirmaOptions options = new VerificaFirmaOptions();
    options.setTipiFirmaAmmessi(tipiFileAmmessiList);
    if (principale) {
        options.setVerificaSigilloQualificato(configuration.sigilloQualificato());
        options.setVerificaFirmaCf(configuration.verificaFirmaCf());
    }
    options.setDescrizione(allegato.getDescrizione());

    VerificaResponse response = firmaRemotaService.verificaFirma(groupId, contesto, allegato.getData(), options);

    boolean verificaFirmaSuDataFineValidita = !verificaFirmaSoloDataOggi;
    boolean firmatoNonValido = response.isFirmatoNonValido();
    boolean presenzaDataFineValidita = response.getDataFineValidita() != null;

    if (verificaFirmaSuDataFineValidita && firmatoNonValido && presenzaDataFineValidita) {
        options.setDataFineValidita(response.getDataFineValidita());
        response = firmaRemotaService.verificaFirma(groupId, contesto, allegato.getData(), options);
    }

    return response;
}

private ServizioDTO getServizioDto(RichiestaReferenteDTO richiesta, DominioIstanza dominio) {
    boolean richiestaIdPresente = richiesta.getRichiestaId() > 0;

    if (richiestaIdPresente) {
        return strategies.get(dominio).getServizio(richiesta.getRichiestaId());
    }

    return strategies.get(dominio).getServizioByProcedimento(richiesta.getProcedimentoId());
}

