43	    @Override
44	    public VerificaResponse verificaFirma(long groupId, Contesto contesto, byte[] file, VerificaFirmaOptions options) {
45	        VerificaResponse response = getClient(groupId).verificaDocumentoFirmato(groupId, contesto, file, options.getDataFineValidita());
46	        Set<String> cfFirme = response.getFirme();
47	
48	        if (cfFirme.isEmpty()) {
49	            throw new VerificaFirmaException(String.format("%s non risulta firmato digitalmente o non ha una firma valida", options.getDescrizione()));
50	        }
51	
52	        if (!options.getTipiFirmaAmmessi().contains(response.getTipoFirma())) {
53	            throw new VerificaFirmaException(String.format("%s ha un tipo di firma non accettato", options.getDescrizione()));
54	        }
55	
56	        if (options.isVerificaSigilloQualificato()) {
57	            if(!response.isSigilloQualificato()) {
58	                throw new VerificaFirmaException(String.format("%s non presenta un sigillo qualificato", options.getDescrizione()));
59	            }
60	        }
61	
62	        if (options.isVerificaFirmaCf()) {
63	            String cfLoggato = options.getCfLoggato().toUpperCase();
64	            if (!cfFirme.contains(cfLoggato)) {
65	                throw new VerificaFirmaException(String.format("%s non risulta firmato dall'utente loggato", options.getDescrizione()));
66	            }
67	        }
68	
69	        return response;
70	    }
