77	    private FirmaRemotaClient getClient(long groupId) {
78	        try {
79	            final List<FirmaRemotaClient> clients = firmaRemotaClient;
80	
81	            FirmaRemotaCommonEnteConfiguration configuration = configurationProvider.getGroupConfiguration(FirmaRemotaCommonEnteConfiguration.class, groupId);
82	
83	            if (configuration.provider() == null) {
84	                throw new FirmaDigitaleRemotaException("Provider non configurato");
85	            }
86	
87	            return clients.stream()
