1	package it.servizidigitali.common.fdr.service.impl;
2	
3	import com.liferay.portal.kernel.module.configuration.ConfigurationProvider;
4	import it.servizidigitali.common.fdr.client.FirmaRemotaClient;
5	import it.servizidigitali.common.fdr.configuration.FirmaRemotaCommonEnteConfiguration;
6	import it.servizidigitali.common.fdr.dto.VerificaFirmaOptions;
7	import it.servizidigitali.common.fdr.dto.VerificaResponse;
8	import it.servizidigitali.common.fdr.exception.VerificaFirmaException;
9	import it.servizidigitali.common.fdr.service.FirmaRemotaService;
10	import it.servizidigitali.common.utility.enumeration.Contesto;
11	import it.servizidigitali.common.utility.exception.FirmaDigitaleRemotaException;
12	import org.osgi.service.component.annotations.Component;
13	import org.osgi.service.component.annotations.Reference;
14	import org.osgi.service.component.annotations.ReferenceCardinality;
15	
16	import java.util.List;
17	import java.util.Set;
18	
19	/**
20	 * Implementazione del servizio di firma digitale remota.
21	 * Gestisce la selezione del client appropriato in base alla configurazione dell'ente
22	 * e delega le operazioni di firma e verifica al provider configurato.
23	 *
24	 * <p>Il servizio supporta piu provider di firma remota e seleziona quello corretto
25	 * in base alla configurazione {@link FirmaRemotaCommonEnteConfiguration}.</p>
26	 *
27	 * @author Servizi Digitali
28	 * @see FirmaRemotaService
29	 * @see FirmaRemotaClient
30	 */
31	@Component(service = FirmaRemotaService.class)
32	public class FirmaRemotaServiceImpl implements FirmaRemotaService {
33	    @Reference(cardinality = ReferenceCardinality.MULTIPLE)
34	    private volatile List<FirmaRemotaClient> firmaRemotaClient;
35	    @Reference
36	    private ConfigurationProvider configurationProvider;
37	
38	    @Override
39	    public byte[] applicaSigillo(long groupId, long userId, Contesto contesto, byte[] pdf, String codiceOtpFirma, String password) {
40	        return getClient(groupId).signWithPades(groupId, userId, contesto, pdf, codiceOtpFirma, password);
41	    }
42	
43	    @Override
44	    public VerificaResponse verificaFirma(long groupId, Contesto contesto, byte[] file, VerificaFirmaOptions options) {
45	        FirmaRemotaClient client = getClient(groupId);
46	        VerificaResponse response = client.verificaDocumentoFirmato(groupId, contesto, file, options.getDataFineValidita());
47	
48	        boolean firmatoNonValido = response.isFirmatoNonValido();
49	        boolean presenzaDataFineValidita = response.getDataFineValidita() != null;
50	        boolean verificaFirmaSuDataFineValidita = options.isVerificaFirmaSuDataFineValidita();
51	
52	        if (firmatoNonValido && verificaFirmaSuDataFineValidita && presenzaDataFineValidita) {
53	            response = client.verificaDocumentoFirmato(groupId, contesto, file, response.getDataFineValidita());
54	        }
55	
56	        Set<String> cfFirme = response.getFirme();
57	
58	        if (cfFirme.isEmpty()) {
59	            throw new VerificaFirmaException(String.format("%s non risulta firmato digitalmente o non ha una firma valida", options.getDescrizione()));
60	        }
61	
62	        if (!options.getTipiFirmaAmmessi().contains(response.getTipoFirma())) {
63	            throw new VerificaFirmaException(String.format("%s ha un tipo di firma non accettato", options.getDescrizione()));
64	        }
65	//jester
66	        /*
67	        if (options.isVerificaSigilloQualificato()) {
68	            if(!response.isSigilloQualificato()) {
69	                throw new VerificaFirmaException(String.format("%s non presenta un sigillo qualificato", options.getDescrizione()));
70	            }
71	        }
72	         */
73	
74	        if (options.isVerificaFirmaCf()) {
75	            String cfLoggato = options.getCfLoggato().toUpperCase();
76	            if (!cfFirme.contains(cfLoggato)) {
77	                throw new VerificaFirmaException(String.format("%s non risulta firmato dall'utente loggato", options.getDescrizione()));
78	            }
79	        }
80	
81	        return response;
82	    }
83	
84	    @Override
85	    public VerificaResponse recuperaImpronta(long groupId, Contesto contesto, byte[] file) {
86	        return getClient(groupId).verificaDocumentoFirmato(groupId, contesto, file, 0);
87	    }
88	
89	    private FirmaRemotaClient getClient(long groupId) {
90	        try {
91	            final List<FirmaRemotaClient> clients = firmaRemotaClient;
92	
93	            FirmaRemotaCommonEnteConfiguration configuration = configurationProvider.getGroupConfiguration(FirmaRemotaCommonEnteConfiguration.class, groupId);
94	
95	            if (configuration.provider() == null) {
96	                throw new FirmaDigitaleRemotaException("Provider non configurato");
97	            }
98	
99	            return clients.stream()
100	                    .filter(o -> o.getProviderName().equals(configuration.provider()))
101	                    .findFirst()
102	                    .orElseThrow();
103	        } catch (Exception e) {
104	            throw new FirmaDigitaleRemotaException(e.getMessage(), e);
105	        }
106	    }
107	}

