287	    private byte[] buildMultipartFilePart(String boundary, byte[] fileBytes) throws Exception {
288	        String header = "--" + boundary + "\r\n"
289	                + "Content-Disposition: form-data; name=\"file\"; filename=\"" + RESOURCE_FILE.substring(1) + "\"\r\n"
290	                + "Content-Type: " + FILE_MIME + "\r\n\r\n";
291	        String footer = "\r\n--" + boundary + "--\r\n";
292	
293	        ByteArrayOutputStream out = new ByteArrayOutputStream();
294	        out.write(header.getBytes(StandardCharsets.UTF_8));
295	        out.write(fileBytes);
296	        out.write(footer.getBytes(StandardCharsets.UTF_8));
297	        return out.toByteArray();
298	    }
