346	    private String buildAuthJson() {
347	        StringBuilder json = new StringBuilder("{");
348	        json.append("\"codiceFiscale\":\"").append(SIGN_CODICE_FISCALE).append("\",");
349	        json.append("\"codiceCertificato\":\"").append(SIGN_CODICE_CERTIFICATO).append("\",");
350	        json.append("\"password\":\"").append(SIGN_PASSWORD).append("\",");
351	        if (SIGN_OTP != null && !SIGN_OTP.isEmpty()) {
352	            json.append("\"otp\":\"").append(SIGN_OTP).append("\"");
353	        } else {
